/**
 * NeuroLink Configuration Types
 * Centralized configuration type definitions following the established architecture pattern
 */
/**
 * Main NeuroLink configuration type
 */
export type NeuroLinkConfig = {
    providers?: Record<string, ProviderConfig>;
    performance?: PerformanceConfig;
    analytics?: AnalyticsConfig;
    tools?: ToolConfig;
    lastUpdated?: number;
    configVersion?: string;
    [key: string]: unknown;
};
/**
 * Provider-specific configuration
 */
export type ProviderConfig = {
    model?: string;
    available?: boolean;
    lastCheck?: number;
    reason?: string;
    apiKey?: string;
    endpoint?: string;
    maxTokens?: number;
    temperature?: number;
    timeout?: number;
    costPerToken?: number;
    features?: string[];
    [key: string]: unknown;
};
/**
 * Performance and caching configuration
 */
export type PerformanceConfig = {
    cache?: CacheConfig;
    fallback?: FallbackConfig;
    timeoutMs?: number;
    maxConcurrency?: number;
    retryConfig?: RetryConfig;
};
/**
 * Cache configuration
 */
export type CacheConfig = {
    enabled?: boolean;
    ttlMs?: number;
    strategy?: "memory" | "writeThrough" | "cacheAside";
    maxSize?: number;
    persistToDisk?: boolean;
    diskPath?: string;
};
/**
 * Fallback configuration
 */
export type FallbackConfig = {
    enabled?: boolean;
    maxAttempts?: number;
    delayMs?: number;
    circuitBreaker?: boolean;
    commonResponses?: Record<string, string>;
    localFallbackPath?: string;
    degradedMode?: boolean;
};
/**
 * Retry configuration
 */
export type RetryConfig = {
    enabled?: boolean;
    maxAttempts?: number;
    baseDelayMs?: number;
    maxDelayMs?: number;
    exponentialBackoff?: boolean;
    retryConditions?: string[];
};
/**
 * Analytics configuration
 */
export type AnalyticsConfig = {
    enabled?: boolean;
    trackTokens?: boolean;
    trackCosts?: boolean;
    trackPerformance?: boolean;
    trackErrors?: boolean;
    exportFormat?: "json" | "csv" | "prometheus";
    exportPath?: string;
    retention?: {
        days?: number;
        maxEntries?: number;
    };
};
/**
 * Tool configuration
 */
export type ToolConfig = {
    /** Whether built-in tools should be disabled */
    disableBuiltinTools?: boolean;
    /** Whether custom tools are allowed */
    allowCustomTools?: boolean;
    /** Maximum number of tools per provider */
    maxToolsPerProvider?: number;
    /** Whether MCP tools should be enabled */
    enableMCPTools?: boolean;
};
/**
 * Backup metadata information
 */
export type BackupInfo = {
    filename: string;
    path: string;
    metadata: BackupMetadata;
    config: NeuroLinkConfig;
};
/**
 * Backup metadata
 */
export type BackupMetadata = {
    reason: string;
    timestamp: number;
    version: string;
    originalPath: string;
    hash?: string;
    size?: number;
    createdBy?: string;
};
/**
 * Configuration validation result
 */
export type ConfigValidationResult = {
    valid: boolean;
    errors: string[];
    warnings: string[];
    suggestions: string[];
};
/**
 * Configuration update options
 */
export type ConfigUpdateOptions = {
    createBackup?: boolean;
    validate?: boolean;
    merge?: boolean;
    reason?: string;
    silent?: boolean;
};
/**
 * Default configuration values
 */
export declare const DEFAULT_CONFIG: NeuroLinkConfig;
